import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"FilterBar","description":"","frontmatter":{},"headers":[],"relativePath":"components/filter-bar.md","filePath":"components/filter-bar.md"}'),i={name:"components/filter-bar.md"};function d(n,e,l,s,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="filterbar" tabindex="-1">FilterBar <a class="header-anchor" href="#filterbar" aria-label="Permalink to &quot;FilterBar&quot;">​</a></h1><p>FilterBar sums up the filters in effect, under the head of a table or a list.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it when a table or a list is filtered, to show how. The filters are built elsewhere, in a modal: pressing a filter opens it (<code>onedit</code>), and its ✕ removes the filter (<code>onremove</code>). With no filter in effect, do not show the bar.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>sentence</code></td><td>required</td><td>How to read the filters, one sentence</td></tr><tr><td><code>items</code></td><td>required</td><td>The filters and the words, <code>FilterBarItem[]</code></td></tr><tr><td><code>onedit</code></td><td></td><td>Called with the id of the filter that is pressed</td></tr><tr><td><code>onremove</code></td><td></td><td>Called with the id of the filter whose ✕ is pressed</td></tr></tbody></table><p>A <code>FilterBarItem</code> is a filter, <code>{ kind: &#39;filter&#39;, id, label }</code>, or a word between filters, <code>{ kind: &#39;word&#39;, text }</code>: a word that joins them, such as &quot;and&quot; or &quot;or&quot;, or a bracket around a group.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A container with pad-md on the raise surface with a line along the bottom, holding two lines gap-sm apart: a funnel and the sentence (caption), then the filters and the words, gap-sm apart, wrapping when they do not fit. Each filter is a <a href="./chip">Chip</a>: its label can be pressed, and its ✕ shows when <code>onremove</code> is given; a long label ends with an ellipsis. The bar is a group named by the <code>filters</code> message, and the ✕ is named by <code>removeFilter</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/filter-bar/" title="FilterBar" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/filter-bar/" target="_blank" rel="noopener">FilterBar</a></figcaption></figure>',11)])])}const m=t(i,[["render",d]]);export{f as __pageData,m as default};
